#include "exgine/gles_probe_material.hpp"
#include <string>
namespace exgine { bool bind_probe_material_set(OpenGLESApi&a,GlUInt program,const ReflectionProbeRegistry&r,const ProbeMaterialSet&s)noexcept{if(!program||!a.ActiveTexture||!a.BindTexture)return false;constexpr GlEnum CUBE=0x8513,T0=0x84C0;for(std::uint32_t i=0;i<s.count&&i<4;i++){auto*g=r.gpu_find(s.probes[i]->id);if(!g||!g->valid)return false;auto bind=[&](GlUInt tex,GlInt loc,GlEnum unit){if(loc>=0){a.ActiveTexture(unit);a.BindTexture(CUBE,tex);a.Uniform1i(loc,GlInt(unit-T0));}};auto irr="u_probe_irradiance"+std::to_string(i),spec="u_probe_specular"+std::to_string(i),pr="u_probe_position_radius"+std::to_string(i),wt="u_probe_weight"+std::to_string(i);bind(g->irradiance,a.GetUniformLocation(program,irr.c_str()),T0+2+i*2);bind(g->specular,a.GetUniformLocation(program,spec.c_str()),T0+3+i*2);auto pl=a.GetUniformLocation(program,pr.c_str()),wl=a.GetUniformLocation(program,wt.c_str());if(pl>=0)a.Uniform4f(pl,s.probes[i]->position.x,s.probes[i]->position.y,s.probes[i]->position.z,s.probes[i]->blend_distance);if(wl>=0)a.Uniform4f(wl,s.weights[i],0,0,0);}auto cl=a.GetUniformLocation(program,"u_probe_count");if(cl>=0)a.Uniform1i(cl,GlInt(s.count));return true;} }